def replace(yaml_dict, template_dict):
    """Replace matched {{...}} in template_dict with values from yaml_dict

    :param yaml_dict: dict representation of a YAML document defining
    placeholder values
    :type yaml_dict: dict
    :param template_dict: dict representation of a YAML document containing
    '{{...}}' string placeholders
    :type template_dict: dict
    :raises PlaceholderNotFoundError: a {{...}} placeholder in template_dict
    was not found in yaml_dict (unless annotated as @optional or @annotation_only)
    :raises ValueError: at least one input parameter is invalid
    :raises NotImplementedError: [description]
    :return: yaml_dict with all '{{...}}' replaced
    :rtype: dict
    """

    # pre-compile the {{...}} placeholder search expression
    # outside `do_replace` to avoid doing it multiple times
    p = re.compile(r'{{([\w\.]+)}}', re.VERBOSE)

    def get_comment_annotations(template_dict, key):
        """Extract annotations from comments for a given key."""
        annotations = {
            'optional': False,
            'annotation_only': False
        }

        if hasattr(template_dict, 'ca') and template_dict.ca.items.get(key):
            comment_info = template_dict.ca.items.get(key)
            comment_token = comment_info[2]  # comment after value
            if comment_token and comment_token.value:
                comment_text = comment_token.value.strip()
                if '@optional' in comment_text:
                    annotations['optional'] = True
                if '@annotation_only' in comment_text:
                    annotations['annotation_only'] = True

        return annotations

    def process_string(yaml_dict, str, annotations=None):
        # determine whether {{...}} placeholder
        # replacement is required
        r = p.search(str)
        if r is None:
            return str
        else:
            root = yaml_dict
            for property in r.group(1).split('.'):
                root = root.get(property)
                if root is None:
                    # Check if this placeholder is optional or annotation_only
                    if annotations and (annotations.get('optional') or annotations.get('annotation_only')):
                        return str  # Return original placeholder for annotation_only, None for optional?
                    raise PlaceholderNotFoundError(r.group(1))
            return root

    def process_list(yaml_dict, list_in, annotations=None):
        list_out = []
        for v in list_in:
            # if v is a string process it
            if (isinstance(v, str)):
                list_out.append(process_string(yaml_dict, v, annotations))
            elif (isinstance(v, dict)):
                list_out.append(do_replace(yaml_dict, v, annotations))
            elif (isinstance(v, list)):
                list_out.append(process_list(yaml_dict, v, annotations))
            else:
                raise NotImplementedError(
                        'Support for properties of type {} in lists '
                        'is not implemented.'
                        .format(type(v)))
        return list_out

    # Recursive function does the actual work
    def do_replace(yaml_dict, template_dict, parent_annotations=None):

        if yaml_dict is None or template_dict is None:
            # nothing to do
            return None

        if not isinstance(yaml_dict, dict):
            raise ValueError('Parameter \'yaml_dict\' must be of type '
                             '\'dict\' not {}.'.format(type(yaml_dict)))

        if not isinstance(template_dict, dict):
            raise ValueError('Parameter \'template_dict\' must be of type '
                             '\'dict\' not {}.'.format(type(template_dict)))

        template_out = {}
        # replace placeholders in the template, one value at a time
        for key in template_dict.keys():
            val = template_dict[key]

            # Get annotations for this specific key
            annotations = get_comment_annotations(template_dict, key)

            # print('Key: {} Value: {} Type: {}'.format(key, val, type(val)))
            if val is None:
                # NoneType - no value
                template_out[key] = None
            elif isinstance(val, str):
                # process string
                processed_val = process_string(yaml_dict, val, annotations)
                # For @annotation_only, keep the placeholder; for @optional missing, set to None
                if annotations.get('annotation_only'):
                    template_out[key] = val  # Keep original placeholder
                elif annotations.get('optional') and p.search(val) and processed_val == val:
                    # Optional placeholder that wasn't found - set to None
                    template_out[key] = None
                else:
                    template_out[key] = processed_val
            elif isinstance(val, dict):
                # process the dictionary recursively
                template_out[key] = do_replace(yaml_dict, val, annotations)
            elif isinstance(val, list):
                # process each list item
                template_out[key] = process_list(yaml_dict, val, annotations)
            else:
                raise NotImplementedError(
                        'Support for properties of type {} is not implemented.'
                        .format(type(val)))

        return template_out

    return do_replace(yaml_dict, template_dict)

